using Essco.Domain.HumanResources;
namespace Essco.Application.HumanResources;
public sealed record EmployeeInput(string Identification,string Code,string Name,string Position,decimal Salary,DateOnly HireDate,bool Active,string Route,string Email,string Phone1,string Phone2,string BankAccount,string CollaboratorId,string LedgerAccount,string Category,decimal VacationEarned,decimal VacationUsed,decimal VacationPending)
{public IReadOnlyCollection<string>Validate(){var e=new List<string>();if(string.IsNullOrWhiteSpace(Identification))e.Add("La cédula es obligatoria.");if(string.IsNullOrWhiteSpace(Code))e.Add("El código es obligatorio.");if(string.IsNullOrWhiteSpace(Name))e.Add("El nombre es obligatorio.");if(HireDate==default)e.Add("La fecha de ingreso es obligatoria.");if(Salary<0)e.Add("El salario no puede ser negativo.");if(VacationEarned<0||VacationUsed<0||VacationPending<0)e.Add("Los valores de vacaciones no pueden ser negativos.");return e;}}
public sealed record EmployeeSaveResult(bool Succeeded,string? Error=null);
public interface IEmployeeRepository{ValueTask<IReadOnlyCollection<Employee>>ListAsync(string?search,bool includeInactive,CancellationToken token);ValueTask<EmployeeFile?>GetAsync(string identification,CancellationToken token);ValueTask<bool>ExistsAsync(string identification,string code,string?excludingIdentification,CancellationToken token);ValueTask<bool>CreateAsync(EmployeeInput input,CancellationToken token);ValueTask<bool>UpdateAsync(string originalIdentification,EmployeeInput input,CancellationToken token);}
public sealed class EmployeeService(IEmployeeRepository repository)
{public ValueTask<IReadOnlyCollection<Employee>>ListAsync(string?s,bool i,CancellationToken t)=>repository.ListAsync(s?.Trim(),i,t);public ValueTask<EmployeeFile?>GetAsync(string id,CancellationToken t)=>repository.GetAsync(id.Trim(),t);public async ValueTask<EmployeeSaveResult>SaveAsync(string?original,EmployeeInput input,CancellationToken token){var x=input with{Identification=input.Identification.Trim(),Code=input.Code.Trim(),Name=input.Name.Trim(),Position=input.Position.Trim(),Route=input.Route.Trim(),Email=input.Email.Trim(),Phone1=input.Phone1.Trim(),Phone2=input.Phone2.Trim(),BankAccount=input.BankAccount.Trim(),CollaboratorId=input.CollaboratorId.Trim(),LedgerAccount=input.LedgerAccount.Trim(),Category=input.Category.Trim()};var error=x.Validate().FirstOrDefault();if(error is not null)return new(false,error);if(await repository.ExistsAsync(x.Identification,x.Code,original,token))return new(false,"Ya existe otro empleado con la misma cédula o código.");var saved=string.IsNullOrWhiteSpace(original)?await repository.CreateAsync(x,token):await repository.UpdateAsync(original,x,token);return new(saved,saved?null:"No fue posible guardar el empleado.");}}
